    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(address newOwner) public {
        require(newOwner != address(this));
        bool ok = c.setOwner(newOwner); if (__ESBMC_reverted()) return;
        require(ok && c.owner() == newOwner);
        bool reverted;
        c.setOwner(newOwner); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }
        assert(reverted && c.owner() == newOwner);
    }
    receive() external payable {}
}

