pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Owned c;

    function setUp() public {
        c = new Owned();
    }

    function _run(address newOwner) internal {
        vm.assume(newOwner != address(this));
        bool ok;
        try c.setOwner(newOwner) returns (bool __r) { ok = __r; } catch { return; }
        newOwner = c.owner();
        vm.assume(ok);
        bool reverted;
        try c.setOwner(newOwner) { reverted = false; } catch { reverted = true; }
        assertTrue(reverted && c.owner() == newOwner);
    }

    function testFuzz_run(address newOwner) public {
        _run(newOwner);
    }

    receive() external payable {}
}
